def solve(rows):
    kept = []
    state = 1
    for i, row in enumerate(rows):
        weight = 0
        if isinstance(row, int):
            weight = row
        elif isinstance(row, str) and row.startswith("|") and row.endswith("|"):
            try:
                weight = int(row[1:-1])
            except ValueError:
                weight = 0
        elif isinstance(row, list):
            for item in row:
                if isinstance(item, int):
                    weight += item
                elif isinstance(item, str):
                    weight += len(item)

        if (state + weight + i) % 11 != 10 or i == len(rows) - 1:
            kept.append(row)
        if weight == 0:
            state = 1
        else:
            state = (3 * state + weight) % 11

    if not kept:
        return []

    final_state = state
    kept_length = len(kept)
    rotation = final_state % kept_length
    rotated_kept = kept[rotation:] + kept[:rotation]

    eligible_days = []
    for row in rotated_kept:
        if isinstance(row, list) and len(row) == 2:
            day, is_blackout = row
            if not is_blackout and day % 4 != 0:
                if isinstance(day, int):
                    eligible_days.append(day)

    distinct_days = sorted(list(set(eligible_days)))[:3]
    return distinct_days

